180: GLuint ILAPIENTRY ilutGLBindTexImage()
181: {
182: 	GLuint	TexID = 0, Target = GL_TEXTURE_2D;
183: 	ILimage *Image;
184: 
185: 	Image = ilGetCurImage();
186: 	if (Image == NULL)
187: 		return 0;
188: 
189: 	if (ilutGetBoolean(ILUT_GL_AUTODETECT_TEXTURE_TARGET)) {
190: 		if (HasCubemapHardware && Image->CubeFlags != 0)
191: 			Target = ILGL_TEXTURE_CUBE_MAP;
192: 		
193: 	}
194: 
195: 	glGenTextures(1, &TexID);
196: 	glBindTexture(Target, TexID);
197: 
198: 	if (Target == GL_TEXTURE_2D) {
199: 		glTexParameteri(Target, GL_TEXTURE_WRAP_S, GL_REPEAT);
200: 		glTexParameteri(Target, GL_TEXTURE_WRAP_T, GL_REPEAT);
201: 	}
202: 	else if (Target == ILGL_TEXTURE_CUBE_MAP) {
203: 		glTexParameteri(Target, GL_TEXTURE_WRAP_S, ILGL_CLAMP_TO_EDGE);
204: 		glTexParameteri(Target, GL_TEXTURE_WRAP_T, ILGL_CLAMP_TO_EDGE);
205: 		glTexParameteri(Target, ILGL_TEXTURE_WRAP_R, ILGL_CLAMP_TO_EDGE);
206: 	}
207: 	glTexEnvi(GL_TEXTURE_ENV, GL_TEXTURE_ENV_MODE, GL_MODULATE);
208: 	glTexParameteri(Target, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
209: 	glTexParameteri(Target, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
210: 	glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
211: 	glPixelStorei(GL_UNPACK_SKIP_ROWS, 0);
212: 	glPixelStorei(GL_UNPACK_SKIP_PIXELS, 0);
213: 	glPixelStorei(GL_UNPACK_ROW_LENGTH, 0);
214: 	glPixelStorei(GL_UNPACK_SWAP_BYTES, IL_FALSE);
215: 
216: 	if (!ilutGLTexImage(0)) {
217: 		glDeleteTextures(1, &TexID);
218: 		return 0;
219: 	}
220: 
221: 	return TexID;
222: }
