225: ILuint GLGetDXTCNum(ILenum DXTCFormat)
226: {
227: 	switch (DXTCFormat)
228: 	{
229: 		// Constants from glext.h.
230: 		case IL_DXT1:
231: 			DXTCFormat = 0x83F1;
232: 			break;
233: 		case IL_DXT3:
234: 			DXTCFormat = 0x83F2;
235: 			break;
236: 		case IL_DXT5:
237: 			DXTCFormat = 0x83F3;
238: 			break;
239: 	}
240: 
241: 	return DXTCFormat;
242: }
