245: // We assume *all* states have been set by the user, including 2D texturing!
246: ILboolean ILAPIENTRY ilutGLTexImage_(GLuint Level, GLuint Target, ILimage *Image)
247: {
248: 	ILimage	*ImageCopy, *OldImage;
249: #if defined (_MSC_VER) || defined (linux) || defined(__APPLE__)
250: 	ILenum	DXTCFormat;
251: 	ILuint	Size;
252: 	ILubyte	*Buffer;
253: #endif
254: 
255: 	if (Image == NULL) {
256: 		ilSetError(ILUT_ILLEGAL_OPERATION);
257: 		return IL_FALSE;
258: 	}
259: 
260: 	OldImage = ilGetCurImage();
261: 
262: #if defined (_MSC_VER) || defined (linux) || defined(__APPLE__)
263: 	if (ilutGetBoolean(ILUT_GL_USE_S3TC) && ilGLCompressed2D != NULL) {
264: 		if (Image->DxtcData != NULL && Image->DxtcSize != 0) {
265: 			DXTCFormat = GLGetDXTCNum(Image->DxtcFormat);
266: 			ilGLCompressed2D(Target, Level, DXTCFormat, Image->Width,
267: 				Image->Height, 0, Image->DxtcSize, Image->DxtcData);
268: 			return IL_TRUE;
269: 		}
270: 
271: 		if (ilutGetBoolean(ILUT_GL_GEN_S3TC)) {
272: 			DXTCFormat = ilutGetInteger(ILUT_S3TC_FORMAT);
273: 
274: 			ilSetCurImage(Image);
275: 			Size = ilGetDXTCData(NULL, 0, DXTCFormat);
276: 			if (Size != 0) {
277: 				Buffer = (ILubyte*)ialloc(Size);
278: 				if (Buffer == NULL) {
279: 					ilSetCurImage(OldImage);
280: 					return IL_FALSE;
281: 				}
282: 
283: 				Size = ilGetDXTCData(Buffer, Size, DXTCFormat);
284: 				if (Size == 0) {
285: 					ilSetCurImage(OldImage);
286: 					ifree(Buffer);
287: 					return IL_FALSE;
288: 				}
289: 
290: 				DXTCFormat = GLGetDXTCNum(DXTCFormat);
291: 				ilGLCompressed2D(Target, Level, DXTCFormat, Image->Width,
292: 					Image->Height, 0, Size, Buffer);
293: 				ifree(Buffer);
294: 				ilSetCurImage(OldImage);
295: 				return IL_TRUE;
296: 			}
297: 			ilSetCurImage(OldImage);
298: 		}
299: 	}
300: #endif//_MSC_VER
301: 
302: 	ImageCopy = MakeGLCompliant2D(Image);
303: 	if (ImageCopy == NULL)
304: 		return IL_FALSE;
305: 
306: 	glTexImage2D(
307: 			Target, 
308: 			Level, 
309: 			ilutGLFormat(ImageCopy->Format, ImageCopy->Bpp),
310: 			ImageCopy->Width,
311: 			ImageCopy->Height,
312: 			0,
313: 			ImageCopy->Format,
314: 			ImageCopy->Type,
315: 			ImageCopy->Data);	
316: 
317: 	if (Image != ImageCopy)
318: 		ilCloseImage(ImageCopy);
319: 
320: 	return IL_TRUE;
321: }
