425: {
426: 	ILimage	*Image;
427: 	ILint Width, Height;
428: 
429: 	ilutCurImage = ilGetCurImage();
430: 	if (ilutCurImage == NULL) {
431: 		ilSetError(ILUT_ILLEGAL_OPERATION);
432: 		return IL_FALSE;
433: 	}
434: 
435: 	Image = MakeGLCompliant2D(ilutCurImage);
436: 	if (Image == NULL)
437: 		return IL_FALSE;
438: 
439: 	glBindTexture(GL_TEXTURE_2D, TexID);
440: 
441: 	glGetTexLevelParameteriv(GL_TEXTURE_2D, 0, GL_TEXTURE_WIDTH,  (GLint*)&Width);
442: 	glGetTexLevelParameteriv(GL_TEXTURE_2D, 0, GL_TEXTURE_HEIGHT, (GLint*)&Height);
