449: 	glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
450: 	glPixelStorei(GL_UNPACK_SKIP_ROWS, 0);
451: 	glPixelStorei(GL_UNPACK_SKIP_PIXELS, 0);
452: 	glPixelStorei(GL_UNPACK_ROW_LENGTH, 0);
453: 	glPixelStorei(GL_UNPACK_SWAP_BYTES, IL_FALSE);
454: 	glTexSubImage2D(GL_TEXTURE_2D, 0, XOff, YOff, Image->Width, Image->Height, Image->Format,
455: 			Image->Type, Image->Data);
456: 
457: 	if (Image != ilutCurImage)
458: 		ilCloseImage(Image);
