511: ILimage* MakeGLCompliant2D(ILimage *Src)
512: {
513: 	ILimage		*Dest = Src, *Temp;
514: 	ILboolean	Created = IL_FALSE;
515: 	ILenum		Filter;
516: 	ILubyte		*Flipped;
517: 	ILboolean   need_resize = IL_FALSE;
518: 	ILint		MaxTexW, MaxTexH;
519: 
520: 	MaxTexW = ilutGetInteger(ILUT_MAXTEX_WIDTH);
521: 	MaxTexH = ilutGetInteger(ILUT_MAXTEX_HEIGHT);
522: 	
523: 	if (Src->Pal.Palette != NULL && Src->Pal.PalSize != 0 && Src->Pal.PalType != IL_PAL_NONE) {
524: 		//ilSetCurImage(Src);
525: 		Dest = iConvertImage(Src, ilGetPalBaseType(Src->Pal.PalType), IL_UNSIGNED_BYTE);
526: 		//Dest = iConvertImage(IL_BGR);
527: 		//ilSetCurImage(ilutCurImage);
528: 		if (Dest == NULL)
529: 			return NULL;
530: 
531: 		Created = IL_TRUE;
532: 
533: 		// Change here!
534: 
535: 
536: 		// Set Dest's palette stuff here
537: 		Dest->Pal.PalType = IL_PAL_NONE;
538: 	}
539: 
540: 	if (HasNonPowerOfTwoHardware == IL_FALSE && 
541: 		  (Src->Width  != ilNextPower2(Src->Width)  ||
542: 		   Src->Height != ilNextPower2(Src->Height)  )) {
543: 				need_resize = IL_TRUE;
544: 			}
545: 
546: 	if ((ILint)Src->Width > MaxTexW || (ILint)Src->Height > MaxTexH)
547: 		need_resize = IL_TRUE;
548: 
549: 	if (need_resize == IL_TRUE) {
550: 		if (!Created) {
551: 			Dest = ilCopyImage_(Src);
552: 			if (Dest == NULL) {
553: 				return NULL;
554: 			}
555: 			Created = IL_TRUE;
556: 		}
557: 
558: 		Filter = iluGetInteger(ILU_FILTER);
559: 		if (Src->Format == IL_COLOUR_INDEX) {
560: 			iluImageParameter(ILU_FILTER, ILU_NEAREST);
561: 			Temp = HasNonPowerOfTwoHardware == IL_TRUE ? 
562: 				iluScale_(Dest, min((ILuint)MaxTexW, Dest->Width), min((ILuint)MaxTexH, Dest->Height), 1)
563: 			  : iluScale_(Dest, min((ILuint)MaxTexW, ilNextPower2(Dest->Width)),
564: 			  		min((ILuint)MaxTexH, ilNextPower2(Dest->Height)), 1);
565: 			iluImageParameter(ILU_FILTER, Filter);
566: 		} else {
567: 			iluImageParameter(ILU_FILTER, ILU_BILINEAR);
568: 			Temp = HasNonPowerOfTwoHardware == IL_TRUE ?
569: 				iluScale_(Dest, min((ILuint)MaxTexW, Dest->Width), min((ILuint)MaxTexH, Dest->Height), 1)
570: 			 :	iluScale_(Dest, min((ILuint)MaxTexW, (ILint)ilNextPower2(Dest->Width)),
571: 			 		min(MaxTexH, (ILint)ilNextPower2(Dest->Height)), 1);
572: 			iluImageParameter(ILU_FILTER, Filter);
573: 		}
574: 
575: 		ilCloseImage(Dest);
576: 		if (!Temp) {
577: 			return NULL;
578: 		}
579: 		Dest = Temp;
580: 	}
581: 
582: 	if (Dest->Origin != IL_ORIGIN_LOWER_LEFT) {
583: 		Flipped = iGetFlipped(Dest);
584: 		ifree(Dest->Data);
585: 		Dest->Data = Flipped;
586: 		Dest->Origin = IL_ORIGIN_LOWER_LEFT;
587: 	}
588: 
589: 	return Dest;
590: }
