891: // From http://www.opengl.org/News/Special/OGLextensions/OGLextensions.html
892: //	Should we make this accessible outside the lib?
893: ILboolean IsExtensionSupported(const char *extension)
894: {
895: 	const GLubyte *extensions;// = NULL;
896: 	const GLubyte *start;
897: 	GLubyte *where, *terminator;
898: 
899: 	// Extension names should not have spaces.
900: 	where = (GLubyte *) strchr(extension, ' ');
901: 	if (where || *extension == '\0')
902: 		return IL_FALSE;
903: 	extensions = glGetString(GL_EXTENSIONS);
904: 	if (!extensions)
905: 		return IL_FALSE;
906: 	// It takes a bit of care to be fool-proof about parsing the
907: 	// OpenGL extensions string. Don't be fooled by sub-strings, etc.
908: 	start = extensions;
909: 	for (;;) {
910: 		where = (GLubyte *)strstr((const char *) start, extension);
911: 		if (!where)
912: 			break;
913: 		terminator = where + strlen(extension);
914: 		if (where == start || *(where - 1) == ' ')
915: 		if (*terminator == ' ' || *terminator == '\0')
916: 			return IL_TRUE;
917: 		start = terminator;
918: 	}
919: 	return IL_FALSE;
920: }
