581: 		ilSetCurImage(CurImage);
582: 		ilSetError(ILUT_ILLEGAL_OPERATION);  // Dunno if this is the correct error.
583: 		ReleaseDC(hWnd, hDC); //added 20040604
584: 		if (TempImage != ilutCurImage)
