679: 
680: 		Bitmap = (HBITMAP)GetClipboardData(CF_BITMAP);
681: 		if (!Bitmap) {
682: 			CloseClipboard();
683: 			return IL_FALSE;  // No error?
684: 		}
685: 
686: 		if (!ilutSetHBitmap(Bitmap)) {
687: 			CloseClipboard();
688: 			return IL_FALSE;
689: 		}
690: 
691: 		CloseClipboard();
692: 	}*/
693: 	
694: 	//no data in clipboard
