	ReadLumpSize = Size;
}


// Tells DevIL that we're writing to a file, not a lump
void iSetOutputFile(ILHANDLE File)
{
	// Helps with ilGetLumpPos().
	WriteLump = NULL;
	WriteLumpPos = 0;
	WriteLumpSize = 0;

	iputc  = iPutcFile;
	iseekw = iSeekWFile;
	itellw = iTellWFile;
	iwrite = iWriteFile;
	FileWrite = File;
}


// This is only called by ilDetermineSize.  Associates iputc, etc. with
